 "content": "def transform(grid):
    """Tile the 8-cells with 2x2 squares and L trominoes, color by orientation."""
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= cells:
                tiles.append((frozenset(box), 1))
            # The color is determined by the missing corner of an L.
            for missing, color in (((r, c), 2), ((r + 1, c), 3),
                                   ((r, c + 1), 4), ((r + 1, c + 1), 5)):
                shape = box - {missing}
                if shape <= cells:
                    tiles.append((frozenset(shape), color))

    by_cell = {p: [] for p in cells}
    for tile in tiles:
        for p in tile[0]:
            by_cell[p].append(tile)

    solutions = []
    def search(remaining, chosen):
        if not remaining:
            solutions.append(chosen)
            return
        p = min(remaining, key=lambda q: sum(shape <= remaining for shape, _ in by_cell[q]))
        for shape, color in by_cell[p]:
            if shape <= remaining:
                search(remaining - shape, chosen + [(shape, color)])
                if len(solutions) > 1:
                    return
    search(cells, [])
    if len(solutions) != 1:
        raise ValueError(f"Expected one tiling, found {len(solutions)}")

    out = [[0] * w for _ in range(h)]
    for shape, color in solutions[0]:
        for r, c in shape:
            out[r][c] = color
    return out
